import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached in-memory bytes for AI Architect screenshots and card banner
class AiArchitectBytes {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String assetPath) {
    if (_cache.containsKey(assetPath)) return _cache[assetPath];
    final base64Str = _data[assetPath];
    if (base64Str == null) return null;
    final bytes = base64Decode(base64Str);
    _cache[assetPath] = bytes;
    return bytes;
  }

  static final Map<String, String> _data = {
    'assets/images/ai_architect_card_banner.png':
        '',
    'assets/images/ai_architect_logo.png':
        '',
    'assets/images/ai_architect/arch_01_splash_screen.png':
        '',
    'assets/images/ai_architect/arch_02_dream_home_design.png':
        '',
    'assets/images/ai_architect/arch_03_interactive_3d_viz.png':
        '',
    'assets/images/ai_architect/arch_04_ai_suggestions.png':
        '',
    'assets/images/ai_architect/arch_05_3d_model_isometric.png':
        '',
    'assets/images/ai_architect/arch_06_floor_plan_ground.png':
        '',
    'assets/images/ai_architect/arch_07_structural_specs.png':
        '',
    'assets/images/ai_architect/arch_08_materials_report.png':
        '',
    'assets/images/ai_architect/arch_09_cost_estimator_boq.png':
        '',
    'assets/images/ai_architect/arch_10_plot_measurement_units.png':
        '',
    'assets/images/ai_architect/arch_11_plot_dimensions_input.png':
        '',
  };
}